{
  "id": "f4a73357-44fc-4c5c-8aa9-df87c5fb7c56",
  "version": "1.8",
  "name": "VendorInvoiceProcessing",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {
        "label": "New Invoice Received"
      },
      "inputs": {
        "entryPointId": "67731dc4-f028-44a3-b5eb-88c5bf94337a",
        "isDefaultEntryPoint": true
      }
    },
    {
      "id": "extractInvoiceFields",
      "type": "core.logic.mock",
      "typeVersion": "1.0",
      "display": {
        "label": "Extract Invoice Fields (mock — deploy IxP model to Orchestrator folder first)"
      }
    },
    {
      "id": "mapFields",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Map Extracted Fields"
      },
      "inputs": {
        "errorHandlingEnabled": true,
        "script": "// Reads IxP extraction output and maps to SAP invoice structure.\n// After swapping the mock for the real IxP node, field access will be via:\n//   $vars.extractInvoiceFields.output.ExtractionResult.ResultsDocument.Fields\nconst ixpOut = $vars.extractInvoiceFields.output || {};\nconst fields = ixpOut.ExtractionResult?.ResultsDocument?.Fields || [];\nconst tables = ixpOut.ExtractionResult?.ResultsDocument?.Tables || [];\nconst get = (name) => fields.find(f => f.FieldName === name)?.Values?.[0] ?? null;\nreturn {\n  invoiceNumber: get('Invoice Number'),\n  vendorName: get('Vendor Name'),\n  invoiceDate: get('Invoice Date'),\n  totalAmount: get('Total Amount'),\n  lineItems: tables\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the node fails",
          "source": "=Error",
          "var": "error",
          "schema": {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "required": ["code", "message", "detail", "category", "status"],
            "properties": {
              "code": { "type": "string", "description": "Error code as a string" },
              "message": { "type": "string", "description": "High-level error message" },
              "detail": { "type": "string", "description": "Detailed error description" },
              "category": { "type": "string", "description": "Error category" },
              "status": { "type": "integer", "description": "HTTP status code" }
            },
            "additionalProperties": false
          }
        }
      }
    },
    {
      "id": "postInvoiceToSap1",
      "type": "uipath.connector.uipath-sap-bapi.execute-bapi-rfc",
      "typeVersion": "1.0.0",
      "display": {
        "label": "Post Invoice to SAP"
      },
      "inputs": {
        "errorHandlingEnabled": true
      }
    },
    {
      "id": "end1",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "End"
      }
    },
    {
      "id": "terminateOnError",
      "type": "core.logic.terminate",
      "typeVersion": "1.0",
      "display": {
        "label": "Terminate on Error"
      }
    }
  ],
