parameters.old_string:
{
  "id": "extractInvoiceFields",
  "type": "core.logic.mock",
  "typeVersion": "1.0",
  "display": {
    "label": "Extract Invoice Fields (mock — deploy IxP model to Orchestrator folder first)"
  }
},

"script": "// Reads IxP extraction output and maps to SAP invoice structure.
// After swapping the mock for the real IxP node, field access will be via:
//   $vars.extractInvoiceFields.output.ExtractionResult.ResultsDocument.Fields
const ixpOut = $vars.extractInvoiceFields.output || {};
const fields = ixpOut.ExtractionResult?.ResultsDocument?.Fields || [];
const tables = ixpOut.ExtractionResult?.ResultsDocument?.Tables || [];
const get = (name) => fields.find(f => f.FieldName === name)?.Values?.[0] ?? null;
return {
  invoiceNumber: get('Invoice Number'),
  vendorName: get('Vendor Name'),
  invoiceDate: get('Invoice Date'),
  totalAmount: get('Total Amount'),
  lineItems: tables
};"

